<template>
  <section class="featured-publication" :class="{ 'is-embedded': embedded }" :aria-label="entry.title">
    <header class="research-feature-head">
      <div v-if="!embedded" class="research-feature-meta"><span>{{ entry.category }}</span><span class="research-feature-status">{{ entry.status }}</span></div>
      <h3 v-if="!embedded" :id="`${entry.id}-research-title`">{{ entry.title }}</h3>
      <p v-if="!embedded && entry.subtitle" class="research-feature-subtitle">{{ entry.subtitle }}</p>
      <div class="research-feature-byline">
        <p class="research-feature-authors" v-html="authorsHtml"></p>
        <a v-if="entry.lab" class="research-feature-lab" :href="entry.lab.url" target="_blank" rel="noopener">
          <img v-if="entry.lab.logo" :src="entry.lab.logo" :alt="entry.lab.name" />
          <span>Associated with <strong>{{ entry.lab.name }}</strong></span>
        </a>
      </div>
    </header>
    <div class="research-feature-prose">
      <p v-for="(paragraph, index) in paragraphs" :key="index" v-html="paragraph"></p>
    </div>
    <div class="research-feature-resources">
      <a v-for="link in entry.links" :key="link.url" class="resource-action" :href="link.url" target="_blank" rel="noopener">
        <span>{{ link.label }}</span>
        <img v-if="link.iconSrc" :src="link.iconSrc" alt="" />
        <ArrowUpRightIcon v-else />
      </a>
    </div>
    <FigureSequence :images="entry.images" :title="entry.title" paper />
    <footer class="research-feature-foot"><SourceViewLinks :source-id="entry.sourceId" /></footer>
  </section>
</template>

<script>
import FigureSequence from './FigureSequence.vue';
import SourceViewLinks from './SourceViewLinks.vue';
import { escapeHtml, escapeRegExp } from '../../utils/highlight';
import '../../assets/css/resource-action.css';

export default {
  name: 'FeaturedPublication',
  components: { FigureSequence, SourceViewLinks },
  props: { entry: { type: Object, required: true }, embedded: Boolean },
  computed: {
    paragraphs() { return this.entry.body.split(/<br\s*\/?>(?:\s*<br\s*\/?>)+/i); },
    authorsHtml() {
      const authors = escapeHtml(this.entry.publication.authors || '');
      const self = this.entry.publication.self;
      return self ? authors.replace(new RegExp(escapeRegExp(self), 'g'), `<strong>${escapeHtml(self)}</strong>`) : authors;
    },
  },

};
</script>

